/// Why a pasteboard change was not recorded. Shown in the lab and counted in
/// diagnostics; never includes content.
public enum CaptureSkipReason: String, Sendable, Equatable, CaseIterable {
    /// Password manager or other app marked it as secret (`ConcealedType`).
    case concealed
    /// Marked as temporary (`TransientType`, legacy markers).
    case transient
    /// Generated by an app, not copied by the user (`AutoGeneratedType`).
    case autoGenerated
    case empty
    /// No type CopyPal can store.
    case unsupported
    /// Larger than the size limit for its kind.
    case tooLarge
    case ignoredApp
    case paused
    /// iPhone copy while "ignore iPhone copies" is set.
    case remoteIgnored
    /// Reading took longer than the timeout.
    case timedOut
    /// The pasteboard changed again while it was being read.
    case changedWhileReading
    /// CopyPal wrote it itself (pasting from the history).
    case ownWrite
    /// macOS does not allow CopyPal to read the pasteboard (privacy setting).
    case accessDenied
}

/// First decision on a pasteboard change, made from the type identifiers alone so
/// marked (secret) content is never read.
public enum PasteboardTypeDecision: Sendable, Equatable {
    case skip(CaptureSkipReason)
    /// Copied on another device (Universal Clipboard).
    case remote
    case read
}

public enum PasteboardMarkers {
    public static func decide(types: [String]) -> PasteboardTypeDecision {
        let set = Set(types)
        if set.isEmpty { return .skip(.empty) }
        if set.contains(PasteboardTypeID.concealed) { return .skip(.concealed) }
        if set.contains(PasteboardTypeID.transient) || !set.isDisjoint(with: PasteboardTypeID.legacyDoNotRecord) {
            return .skip(.transient)
        }
        if set.contains(PasteboardTypeID.autoGenerated) { return .skip(.autoGenerated) }
        if set.isDisjoint(with: readableTypes) { return .skip(.unsupported) }
        if set.contains(PasteboardTypeID.remoteClipboard) { return .remote }
        return .read
    }

    /// Types that make a copy worth reading (TIFF is converted to PNG when read).
    static let readableTypes: Set<String> = Set(PasteboardTypeID.stored).union([
        PasteboardTypeID.tiff,
        PasteboardTypeID.rtfd,
        "NSStringPboardType",
        "NSFilenamesPboardType",
    ])
}
